import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇789｜超脱者与制度·超脱者的法律约束与豁免边界","description":"","frontmatter":{"title":"篇789｜超脱者与制度·超脱者的法律约束与豁免边界","no":789,"module":4,"tags":["超脱","制度","法律约束","豁免边界","共生宪法"],"related":["0040-共生宪法总纲","0048-司法体系与裁决机制","784-超脱者与制度总论"]},"headers":[],"relativePath":"zh/0789_模块4-制度-法律约束与豁免边界.md","filePath":"zh/0789_模块4-制度-法律约束与豁免边界.md"}'),e={name:"zh/0789_模块4-制度-法律约束与豁免边界.md"};function i(n,t,s,u,h,q){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇789-超脱者与制度·超脱者的法律约束与豁免边界" tabindex="-1">篇789｜超脱者与制度·超脱者的法律约束与豁免边界 <a class="header-anchor" href="#篇789-超脱者与制度·超脱者的法律约束与豁免边界" aria-label="Permalink to &quot;篇789｜超脱者与制度·超脱者的法律约束与豁免边界&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档40、48、784</p></blockquote><h2 id="引言-超脱者有没有-法外之地" tabindex="-1">引言：超脱者有没有&quot;法外之地&quot; <a class="header-anchor" href="#引言-超脱者有没有-法外之地" aria-label="Permalink to &quot;引言：超脱者有没有&quot;法外之地&quot;&quot;">​</a></h2><p>前面几篇反复说&quot;超脱者和万族适用同一部法律&quot;。但现实问题不能回避：<strong>超脱者在紧急情况下，有没有短暂的法律豁免？</strong> 比如位面级灾难即将发生，超脱者来不及走报备程序，他能不能先出手？本篇就是回答这个&quot;豁免边界&quot;问题——不是否定&quot;法律面前人人平等&quot;，而是划出紧急情况下的窄门。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求豁免不含掠夺；万族共和公理要求豁免对万族公平；集体升维公理要求豁免服务于升维；因果自律公理要求豁免严格限定在紧急范围；法则优先公理要求豁免边界在法则层面清晰、不可被扩张。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、豁免的三个法定条件" tabindex="-1">一、豁免的三个法定条件 <a class="header-anchor" href="#一、豁免的三个法定条件" aria-label="Permalink to &quot;一、豁免的三个法定条件&quot;">​</a></h2><p>衡元宙不搞&quot;超脱者法外开恩&quot;，但确实给了一种极窄的法定豁免——&quot;紧急避险豁免&quot;。这个豁免只有在三个条件同时满足时才生效：</p><ol><li><strong>紧急性</strong>：位面级灾难（星域级因果断裂、跨位面污染爆发、万族级生命威胁）正在发生，不走豁免就来不及了</li><li><strong>必要性</strong>：超脱者采取的行动是当时唯一能阻止灾难的手段，没有替代方案</li><li><strong>即时性</strong>：豁免只在灾难发生的当下有效，灾难一过，豁免立即终止</li></ol><p>三个条件缺一不可。任何一个不满足，超脱者就没有豁免，必须走正常程序。</p><h2 id="二、豁免的三个禁止扩张" tabindex="-1">二、豁免的三个禁止扩张 <a class="header-anchor" href="#二、豁免的三个禁止扩张" aria-label="Permalink to &quot;二、豁免的三个禁止扩张&quot;">​</a></h2><p>豁免有严格的禁止扩张规则：</p><ul><li><strong>禁止时间扩张</strong>：豁免只覆盖灾难进行时，不能延伸到灾难结束后的&quot;善后&quot;。善后必须走正常程序</li><li><strong>禁止范围扩张</strong>：豁免只覆盖阻止灾难所必需的最小行动，不能借豁免&quot;顺手&quot;做别的事</li><li><strong>禁止身份扩张</strong>：豁免只属于正在采取紧急行动的超脱者个人，不能延伸到其同门、同族、下属</li></ul><p>三条禁止确保豁免是一扇窄门，不是一扇大开的后门。</p><h2 id="三、豁免后的强制程序" tabindex="-1">三、豁免后的强制程序 <a class="header-anchor" href="#三、豁免后的强制程序" aria-label="Permalink to &quot;三、豁免后的强制程序&quot;">​</a></h2><p>豁免不是&quot;白免&quot;。超脱者在紧急避险豁免后，必须走以下强制程序：</p><ol><li><strong>即时报告</strong>：灾难结束后一个周期内，超脱者必须向锚点监督委员会提交完整的行动报告</li><li><strong>事后审计</strong>：监督委员会审计豁免期间的全部操作，确认是否真的满足三条件</li><li><strong>因果修复</strong>：豁免行动造成的因果扰动，超脱者必须在后续岗位工作中修复</li><li><strong>公开通报</strong>：审计结果向万族公开通报，接受万族代表质询</li></ol><p>四步程序确保豁免不是&quot;逃责通道&quot;，而是&quot;先干后报&quot;。</p><h2 id="四、绝对不可豁免的行为" tabindex="-1">四、绝对不可豁免的行为 <a class="header-anchor" href="#四、绝对不可豁免的行为" aria-label="Permalink to &quot;四、绝对不可豁免的行为&quot;">​</a></h2><p>有些行为，即使在紧急情况下，超脱者也绝对不能豁免：</p><ul><li><strong>掠夺行为</strong>：任何形式的掠夺、吞噬、夺取，永远不在豁免范围内</li><li><strong>剥夺万族成长权</strong>：替万族做决定、替万族扛因果，永远不在豁免范围内</li><li><strong>改写历史</strong>：跨位面时间线直接改写，永远不在豁免范围内</li><li><strong>消灭族群</strong>：任何形式的种族灭绝，永远不在豁免范围内</li></ul><p>四条红线是衡元宙的&quot;绝对不可豁免清单&quot;。哪怕天塌下来，超脱者也不能踩这四条线。踩了，即使是为了&quot;救世&quot;，也按犯罪论处。</p><p>豁免不是&quot;免罪金牌&quot;，而是&quot;紧急时刻的临时让路&quot;。每一次豁免的使用，都必须在事后接受双重审计：阿赖耶网络的行为数据审计，和锚点监督委员会的伦理审计。审计结论分为三档——合规、瑕疵、越权。合规者不留污点；瑕疵者要求补充说明并记入档案；越权者不仅豁免作废，还要按普通违法追加追责。关键原则是：豁免只覆盖&quot;为了阻止更大恶而不得不做的那部分行为&quot;，超出这个范围的部分一律不豁免。比如为了阻止掠夺派核弹而摧毁一座空建筑可以豁免，但顺手抢了建筑里的资源不豁免。边界划得极细，不给任何人留&quot;紧急状态&quot;的想象空间。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：豁免边界防止超脱者借紧急情况滥用权力，把算力用在正道上</li><li><strong>反掠夺</strong>：掠夺行为绝对不可豁免，从法律层面封死&quot;紧急掠夺&quot;的借口</li><li><strong>唐罗上限对比</strong>：唐罗体系里超脱者没有任何法律约束；衡元宙只给了一扇极窄的紧急避险豁免门</li><li><strong>万族全覆盖</strong>：豁免对万族一切生灵适用，超脱者不享有特殊豁免权</li><li><strong>超多元全开放</strong>：豁免的全部规则、案例、审计结果通过无私道全网开放。衡锚超多元境超脱者行使紧急避险豁免时，由阿赖耶网络+多层监督全程记录，事后计入文明权重</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者有没有法外之地？有一扇极窄的门——紧急避险豁免。但这扇门只在天塌下来的时候开，天一停就关，而且门后还有强制审计、因果修复、公开通报。除此之外，超脱者和万族适用同一部法律，没有任何特权。窄门是为了救人，不是为了放人。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0040-共生宪法总纲.html">0040-共生宪法总纲</a> · <a href="./0048-司法体系与裁决机制.html">0048-司法体系与裁决机制</a> · <a href="./0784_模块4-制度-总论.html">784-超脱者与制度总论</a> · <a href="./0083-先观测后有限干涉准则.html">0083-先观测后有限干涉准则</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',29)])])}const p=o(e,[["render",i]]);export{_ as __pageData,p as default};
